import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type DollarCounterProps = Record<string, any>;

const DollarCounter: React.FC<DollarCounterProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
  targetAmount = 1671000,
  currencySymbol = "$",
  soldText = "SOLD",
  mainTextColor = "#ffffff",
  stickerColor = "#e74c3c",
  stickerTextColor = "#ffffff",
  stickerRotation = -15,
  fontSize = 120,
}) => {
  useFontLoader(["Oswald", "Black Ops One"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Timing Configuration ---
  const totalFrames = durationInSeconds * fps;
  // Spend 60% of the time counting so it finishes well before the sticker
  const countDurationFrames = Math.floor(totalFrames * 0.6);
  // Start sticker animation at 70% of timeline to ensure a clear pause/separation
  const stickerDelayFrames = Math.floor(totalFrames * 0.7);

  // --- Logic to prevent parser errors ---
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Counter Animation ---
  const currentAmount = interpolate(
    frame,
    [0, countDurationFrames],
    [0, targetAmount],
    {
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.exp),
    }
  );

  const formattedAmount = `${currencySymbol}${Math.floor(currentAmount).toLocaleString("en-US")}`;

  // --- Sticker Animation ---
  // Calculates the spring for the sticker impact
  // Adjusted for a faster "pop" (higher stiffness, lower mass)
  const stickerSpring = spring({
    frame: frame - stickerDelayFrames,
    fps,
    config: {
      damping: 12,
      stiffness: 300,
      mass: 0.5,
    },
  });

  const stickerScale = interpolate(stickerSpring, [0, 1], [0, 1]);
  // Add a slight alpha fade-in with the scale
  const stickerOpacity = interpolate(frame, [stickerDelayFrames, stickerDelayFrames + 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate dynamic positions
  const centerX = width / 2;
  const centerY = height / 2;

  // Render
  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Oswald",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Main Counter Text */}
      <div
        style={{
          color: mainTextColor,
          fontSize: `${fontSize}px`,
          fontWeight: 700,
          fontVariantNumeric: "tabular-nums", // Keeps numbers monospaced to prevent jitter
          zIndex: 1,
          transition: "none",
        }}
      >
        {formattedAmount}
      </div>

      {/* SOLD Sticker Overlay */}
      {frame > stickerDelayFrames && (
        <div
          style={{
            position: "absolute",
            left: centerX,
            top: centerY,
            transform: `translate(-50%, -50%) rotate(${stickerRotation}deg) scale(${stickerScale})`,
            backgroundColor: stickerColor,
            color: stickerTextColor,
            padding: `${fontSize * 0.1}px ${fontSize * 0.4}px`,
            border: `${fontSize * 0.05}px solid ${stickerTextColor}`,
            borderRadius: `${fontSize * 0.1}px`,
            fontFamily: "Black Ops One",
            fontSize: `${fontSize * 0.8}px`, // Sticker slightly smaller than number text
            lineHeight: 1,
            textTransform: "uppercase",
            whiteSpace: "nowrap",
            boxShadow: "0 10px 20px rgba(0,0,0,0.4)",
            opacity: stickerOpacity,
            zIndex: 10,
            transition: "none",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            // create a "grunge" or "stamp" look with a rough border style
            outline: `${fontSize * 0.02}px dashed ${stickerTextColor}`,
            outlineOffset: `-${fontSize * 0.08}px`,
          }}
        >
          {soldText}
        </div>
      )}
    </AbsoluteFill>
  );
};

export default DollarCounter;